const SNAPSHOT_THUMB = /^\/snapshots\/[a-f0-9]{40}\/thumb\.webp$/

export function previewScreenshotCandidates(source: string | null): string[] {
  if (!source) return []

  let url: URL
  try {
    url = new URL(source)
  }
  catch {
    return []
  }

  if (url.protocol !== 'https:' && url.protocol !== 'http:') return []

  // Both variants are generated by UrlSnapshotService for every plan. Never
  // rewrite third-party, legacy or signed URLs; the original is the fallback.
  const isSnapshot = url.origin === 'https://cdn.launchlog.ai'
    && SNAPSHOT_THUMB.test(url.pathname)
    && !url.username && !url.password && !url.hash
    && [...url.searchParams].every(([key, value]) => key === 'v' && /^\d+$/.test(value))

  if (!isSnapshot) return [source]

  url.pathname = url.pathname.replace(/thumb\.webp$/, 'featured.webp')
  return [url.toString(), source]
}
